#pragma once

#include <array>
#include <string>
#include <vector>

namespace localpinyin {

// What the tool panel lists, shared by the input method's small panel and
// the settings app's large one: symbols, kaomoji and emoji (from
// dictionary\panel\*.tsv, generated by tools/generate_panel_data.py), the
// user's favorites and recent picks (desktop\panel.json in the data folder,
// written by both) and the user's stickers (stickers\index.json).
enum class PanelKind { Symbol = 0, Kaomoji = 1, Emoji = 2 };

struct PanelItem {
    std::wstring text;
    std::wstring name;
    std::vector<std::wstring> keywords;
};

struct PanelGroup {
    std::wstring id;
    std::wstring name;
    std::vector<PanelItem> items;  // sections one after another
};

class PanelCatalog {
public:
    bool load(const std::wstring& tsv_path);
    [[nodiscard]] const std::vector<PanelGroup>& groups() const noexcept { return groups_; }
    [[nodiscard]] const PanelItem* find(const std::wstring& text) const;
    [[nodiscard]] bool empty() const noexcept { return groups_.empty(); }

private:
    std::vector<PanelGroup> groups_;
};

// Favorites and recents per kind, as in panel.json.
struct PanelUserState {
    std::array<std::vector<std::wstring>, 3> favorites;
    std::array<std::vector<std::wstring>, 3> recents;

    static constexpr size_t kRecentLimit = 48;
    static PanelUserState load(const std::wstring& path);
    bool save(const std::wstring& path) const;
    // Picks go first in their kind's recents, latest first.
    void remember(PanelKind kind, const std::vector<std::wstring>& picks);
};

struct Sticker {
    std::wstring id;
    std::wstring ext;
    std::wstring name;
};

std::vector<Sticker> load_stickers(const std::wstring& index_path);

// Item text matching a search: its text, name or keywords contain `needle`
// (case-insensitive for letters).
bool panel_item_matches(const PanelItem& item, const std::wstring& needle);
bool contains_folded(const std::wstring& haystack, const std::wstring& needle);

}  // namespace localpinyin
